<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>落地页预览</title>
<style>
:root{
  --bg:#14161a; --panel:#1b1e24; --panel-2:#20242b; --line:#2b3038; --line-hi:#3a4048;
  --ink:#e8e6e1; --ink-2:#a8adb6; --muted:#71767f;
  --mark:#e8402a;          /* 暗房红蜡笔：选中、计数、当前项 */
  --live:#3fae9b;          /* 实时回源 */
  --warn:#d8a13a;          /* 仅本地可见（目录以 _ 结尾，rsync 会跳过）*/
  --mono:ui-monospace,"SF Mono",SFMono-Regular,Menlo,"Cascadia Mono",monospace;
  --sans:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans","Noto Sans KR",sans-serif;
  --card-w:220px; --card-w-px:220;
}
*{box-sizing:border-box}
html,body{margin:0;height:100%}
body{
  background:var(--bg); color:var(--ink);
  font:13px/1.5 var(--mono);
  -webkit-font-smoothing:antialiased;
  display:grid; grid-template-rows:auto 1fr; height:100vh; overflow:hidden;
}
button,input,select{font:inherit;color:inherit}
::selection{background:var(--mark);color:#fff}

/* ---------- 顶栏 ---------- */
header{
  border-bottom:1px solid var(--line); background:var(--panel);
  display:flex; align-items:center; gap:14px; padding:0 14px; height:52px;
}
.brand{font-family:var(--sans);font-weight:650;letter-spacing:-.02em;font-size:14px;white-space:nowrap}
.brand em{font-style:normal;color:var(--mark)}
.count{color:var(--muted);font-size:11px;white-space:nowrap}
.search{
  flex:1; min-width:120px; max-width:420px; background:var(--bg); border:1px solid var(--line);
  padding:7px 10px; outline:none; border-radius:0;
}
.search:focus{border-color:var(--mark)}
.search::placeholder{color:var(--muted)}
.ctl{display:flex;align-items:center;gap:6px;white-space:nowrap}
.ctl label{color:var(--muted);font-size:11px}
select{background:var(--bg);border:1px solid var(--line);padding:6px 8px;outline:none;border-radius:0}
select:focus{border-color:var(--mark)}
.toggle{
  background:var(--bg);border:1px solid var(--line);padding:6px 9px;cursor:pointer;
  color:var(--muted);font-size:11px;user-select:none
}
.toggle[aria-pressed="true"]{border-color:var(--mark);color:var(--ink)}
.toggle:hover{border-color:var(--line-hi)}
.seg{display:flex;border:1px solid var(--line);background:var(--bg)}
.seg button{background:none;border:0;padding:6px 11px;color:var(--muted);cursor:pointer;
  font-size:11px;white-space:nowrap}
.seg button+button{border-left:1px solid var(--line)}
.seg button:hover:not(.on){color:var(--ink-2)}
.seg button.on{background:var(--panel-2);color:var(--ink);box-shadow:inset 0 -2px 0 var(--mark)}

/* ---------- 主体 ---------- */
.body{display:grid;grid-template-columns:210px 1fr;min-height:0}
aside{border-right:1px solid var(--line);background:var(--panel);overflow-y:auto;padding:10px 0 40px}
.tree-h{padding:6px 14px;color:var(--muted);font-size:10px;letter-spacing:.12em;text-transform:uppercase}
.tree a{
  display:flex;justify-content:space-between;gap:8px;padding:4px 14px;color:var(--ink-2);
  text-decoration:none;cursor:pointer;border-left:2px solid transparent
}
.tree a:hover{background:var(--panel-2);color:var(--ink)}
.tree a.on{border-left-color:var(--mark);color:var(--ink);background:var(--panel-2)}
.tree a .n{color:var(--muted);font-size:11px}
.tree a.sub{padding-left:26px;font-size:12px;color:var(--muted)}
.tree a.sub:hover{color:var(--ink-2)}

main{overflow-y:auto;padding:0 14px 120px;scroll-behavior:smooth}

/* ---------- 分组 ---------- */
.group{margin-top:22px}
.group-h{
  position:sticky;top:0;z-index:5;background:var(--bg);display:flex;align-items:center;gap:10px;
  padding:8px 0 7px;border-bottom:1px solid var(--line);cursor:pointer;user-select:none
}
.group-h h2{margin:0;font:600 13px/1 var(--sans);letter-spacing:.01em}
.group-h .n{color:var(--mark);font-size:11px}
.group-h .chev{color:var(--muted);font-size:10px;transition:transform .15s}
.group.closed .chev{transform:rotate(-90deg)}
.group.closed .grid,.group.closed .subgroup{display:none}
.sub-h{
  display:flex;align-items:baseline;gap:8px;padding:14px 0 6px;color:var(--ink-2);
  font-size:11px;letter-spacing:.08em;text-transform:uppercase
}
.sub-h .n{color:var(--muted);text-transform:none;letter-spacing:0}
.sub-h::after{content:"";flex:1;height:1px;background:var(--line)}

.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(var(--card-w),1fr));gap:10px}

/* ---------- 卡片（一格底片） ---------- */
.frame{
  border:1px solid var(--line);background:var(--panel);cursor:pointer;outline:none;
  display:flex;flex-direction:column;transition:border-color .12s
}
.frame:hover,.frame:focus-visible{border-color:var(--mark)}
.frame:focus-visible{box-shadow:0 0 0 1px var(--mark)}
.shot{
  position:relative;aspect-ratio:390/844;overflow:hidden;background:#0c0e11;
  border-bottom:1px solid var(--line)
}
.shot img{position:absolute;inset:0;width:100%;display:block}
.shot img.card{height:100%;object-fit:cover;object-position:top}
/* 签名动作：悬停时沿整条底片扫过一遍 */
.shot img.full{height:auto;opacity:0;transition:opacity .18s;transform:translateY(0)}
.frame:hover .shot img.full{
  opacity:1;transform:translateY(calc(-100% * (1 - 1 / var(--ratio,1))));
  transition:opacity .18s,transform 2.6s cubic-bezier(.4,0,.5,1)
}
.frame:hover .shot img.card{opacity:0;transition:opacity .18s}
.shot iframe{
  position:absolute;top:0;left:0;width:390px;height:844px;border:0;background:#fff;
  transform:scale(calc(var(--card-w-px) / 390));transform-origin:top left;pointer-events:none
}
.seq{
  position:absolute;top:0;left:0;z-index:2;background:rgba(10,12,15,.72);color:var(--ink-2);
  font-size:9px;letter-spacing:.06em;padding:2px 5px
}
.badge{position:absolute;top:0;right:0;z-index:2;font-size:9px;padding:2px 5px;
  letter-spacing:.04em;background:rgba(10,12,15,.78)}
.badge.live{color:var(--live)}
.badge.none{color:var(--muted)}
.placeholder{
  position:absolute;inset:0;display:grid;place-content:center;gap:6px;text-align:center;
  color:var(--muted);font-size:10px;padding:12px;line-height:1.7
}
.meta{padding:6px 7px 7px;display:flex;flex-direction:column;gap:3px;min-width:0}
.meta .path{color:var(--ink-2);font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.meta .t{font-family:var(--sans);font-size:11.5px;color:var(--ink);overflow:hidden;
  text-overflow:ellipsis;white-space:nowrap}
.tags{display:flex;gap:4px;flex-wrap:wrap;margin-top:1px}
.tag{font-size:9px;color:var(--muted);border:1px solid var(--line);padding:0 4px;line-height:15px}
.tag.ch{color:var(--ink-2);border-color:var(--line-hi)}
.tag.x{color:var(--mark);border-color:transparent;padding-left:0}
.tag.local{color:var(--warn);border-color:transparent;padding-left:0}
.tag.note{color:var(--live);border-color:transparent;padding-left:0}

.empty{padding:60px 0;text-align:center;color:var(--muted);line-height:2}

/* ---------- 抽屉 ---------- */
.scrim{position:fixed;inset:0;background:rgba(8,9,11,.66);opacity:0;pointer-events:none;
  transition:opacity .18s;z-index:20}
.scrim.on{opacity:1;pointer-events:auto}
.drawer{
  position:fixed;top:0;right:0;bottom:0;width:min(860px,100vw);background:var(--panel);
  border-left:1px solid var(--line-hi);z-index:21;transform:translateX(100%);
  transition:transform .22s cubic-bezier(.3,0,.2,1);display:grid;grid-template-columns:390px 1fr
}
.drawer.on{transform:none}
.dv{border-right:1px solid var(--line);background:#0c0e11;overflow:hidden;position:relative}
.dv iframe{width:390px;height:100%;border:0;display:block;background:#fff}
.dp{overflow-y:auto;padding:16px 16px 40px;display:flex;flex-direction:column;gap:14px;min-width:0}
.dp h3{margin:0;font:600 15px/1.35 var(--sans);letter-spacing:-.01em}
.dp .desc{color:var(--ink-2);font-size:11.5px;line-height:1.65;font-family:var(--sans)}
.row{display:flex;flex-direction:column;gap:5px}
.row .k{color:var(--muted);font-size:10px;letter-spacing:.1em;text-transform:uppercase}
.linkbar{display:flex;border:1px solid var(--line);background:var(--bg)}
.linkbar span{flex:1;padding:7px 9px;font-size:10.5px;overflow:hidden;text-overflow:ellipsis;
  white-space:nowrap;color:var(--ink-2)}
.linkbar button{background:none;border:0;border-left:1px solid var(--line);padding:0 10px;
  cursor:pointer;color:var(--muted);font-size:10px;letter-spacing:.06em}
.linkbar button:hover{color:var(--mark)}
.dp select{width:100%}
.dp .src{color:var(--muted);font-size:10.5px;word-break:break-all}
.kv{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;font-size:11px;color:var(--ink-2)}
.kv b{color:var(--muted);font-weight:400}
.dclose{position:absolute;top:8px;right:8px;z-index:3;background:rgba(10,12,15,.8);
  border:1px solid var(--line-hi);color:var(--ink-2);width:26px;height:26px;cursor:pointer;line-height:1}
.dclose:hover{color:var(--mark);border-color:var(--mark)}
.hint{color:var(--muted);font-size:10px;line-height:1.7}
kbd{border:1px solid var(--line-hi);padding:0 4px;font-size:9px;color:var(--ink-2)}

@media (max-width:900px){
  .body{grid-template-columns:1fr}
  aside{display:none}
  .drawer{grid-template-columns:1fr;width:100vw}
  .dv{display:none}
}
@media (prefers-reduced-motion:reduce){
  *{transition-duration:.01ms!important}
  .frame:hover .shot img.full{transform:none}
}
</style>
