<body>

<header>
  <div class="brand">落地页<em>预览</em></div>
  <div class="count" id="count">读取索引…</div>
  <input class="search" id="q" placeholder="搜索标题 / 路径 / 人物 / 备注   ( / )" autocomplete="off">
  <div class="ctl">
    <label for="groupBy">分组</label>
    <select id="groupBy">
      <option value="region+category">区域 → 人物·分类</option>
      <option value="region">区域</option>
      <option value="category">人物·分类</option>
      <option value="month">日期（按月）</option>
      <option value="channel">渠道</option>
      <option value="suffix">变体后缀</option>
      <option value="">不分组</option>
    </select>
  </div>
  <div class="ctl">
    <label for="sortBy">排序</label>
    <select id="sortBy">
      <option value="date">日期新→旧</option>
      <option value="path">路径</option>
      <option value="variants">变体数</option>
    </select>
  </div>
  <div class="ctl">
    <label>排版</label>
    <div class="seg" id="segLayout" role="group" aria-label="排版">
      <button data-w="150">紧凑</button>
      <button data-w="220" class="on">标准</button>
      <button data-w="300">大图</button>
    </div>
  </div>
</header>

<div class="body">
  <aside><div class="tree-h">目录</div><nav class="tree" id="tree"></nav></aside>
  <main id="main"><div class="empty">读取索引…</div></main>
</div>

<div class="scrim" id="scrim"></div>
<div class="drawer" id="drawer" role="dialog" aria-label="页面预览">
  <div class="dv">
    <button class="dclose" id="dclose" title="关闭 (Esc)">×</button>
    <iframe id="dframe" sandbox="allow-scripts allow-same-origin" referrerpolicy="no-referrer"></iframe>
  </div>
  <div class="dp" id="dpanel"></div>
</div>

<script>
const PROD = 'https://t.dd-ll.xyz'
const DEV = 'http://localhost:4321'
const HERE = location.origin
/* 画廊本身既可能跑在 dev，也可能跑在生产域名下 */
const ONLINE = !/^https?:\/\/(?:localhost|127\.|\[::1\])/.test(HERE)
/* 线上一律不自动回源：iframe 打开的是真实生产页，SSI 注入的 FB Pixel / GA 会真的打点，
   批量自动加载等于给这些落地页刷假量。线上缺图就显示占位，让人自己决定点开哪一张。 */
const MAX_LIVE = ONLINE ? 0 : 24
/* 本地入口在 /_gallery/index.html，缩略图就在旁边；线上入口是根目录的 index.php，要带前缀 */
const SHOTS_BASE = window.__SHOTS_BASE__ ?? 'shots/'
const CH_LABEL = {
  卡扣:'卡扣', 卡群:'卡群', 棒群:'棒群', 混合:'混合', 引导弹窗:'弹窗', 提高质量_:'表单',
  kakao:'kakao', band:'band', 'modal-kakao':'弹窗', 'form-kakao':'表单', choice:'选择',
}

let DATA = [], SHOTS = {}, view = [], current = null
const state = { q: '', groupBy: 'region+category', sortBy: 'date', cardW: 220 }

const $ = s => document.querySelector(s)
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))

/* dev server 下 public/ 里的静态页必须带 index.html 才打得开（目录 URL 会 404）；
   线上 nginx 自己会找 index，不能加。 */
const needsIndex = (t, url) => t.source.startsWith('public/') && url.endsWith('/')
const prodUrl = (t, url) => PROD + url
const hereUrl = (t, url) => HERE + encodeURI(!ONLINE && needsIndex(t, url) ? `${url}index.html` : url)

function shotState(t){
  const s = SHOTS[t.id]
  if (!s) return 'none'
  return s.hash === t.rep.hash ? 'fresh' : 'stale'
}

async function load(){
  /* 线上由 index.php 在密码门后把索引内嵌进页面（见 scripts/gallery/bundle.mjs）；
     本地 dev 没有 PHP，走静态 JSON。 */
  const boot = window.__GALLERY__
  const [idx, shots] = boot
    ? [boot.index, boot.shots]
    : await Promise.all([
      fetch('./index.json').then(r => r.json()),
      fetch('./shots.json').then(r => r.ok ? r.json() : {}).catch(() => ({})),
    ])
  DATA = idx.templates.filter(t => !t.fragment && !t.private
    && t.region !== 'common' && t.region !== 'test' && t.region !== 'YY')
  SHOTS = shots
  const shot = DATA.filter(t => shotState(t) !== 'none').length
  $('#count').textContent = `${DATA.length} 个版式 · 已截图 ${shot}`
  render()
}

/* ---------- 筛选 / 排序 / 分组 ---------- */
function filtered(){
  const q = state.q.trim().toLowerCase()
  return DATA.filter((t) => {
    if (!q) return true
    return (t.title + ' ' + t.rep.url + ' ' + (t.category ?? '') + ' ' + (t.note ?? '')
      + ' ' + t.people.join(' ') + ' ' + (t.description ?? '')).toLowerCase().includes(q)
  })
}

const monthOf = t => t.date ? t.date.slice(0, 6).replace(/(\d{4})(\d{2})/, '$1-$2') : '无日期'
const keyOf = (t, dim) => ({
  region: t.region,
  category: t.category ?? '—',
  month: monthOf(t),
  channel: t.channels.length ? t.channels.map(c => CH_LABEL[c] ?? c).join('/') : '无渠道',
  suffix: t.suffix ?? '—',
}[dim] ?? '')

function sorted(list){
  const by = state.sortBy
  return list.slice().sort((a, b) =>
    by === 'variants' ? b.variantCount - a.variantCount
    : by === 'path' ? a.rep.url.localeCompare(b.rep.url)
    : (b.date ?? '').localeCompare(a.date ?? '') || a.rep.url.localeCompare(b.rep.url))
}

/* ---------- 渲染 ---------- */
function cardHTML(t, seq){
  const st = shotState(t)
  const ratio = Math.max(1, (SHOTS[t.id]?.height ?? 844) / 844)
  const shot = st === 'none'
    ? `<div class="placeholder" data-live="${esc(hereUrl(t, t.rep.url))}">未截图<br><span>bun run gallery:shots</span></div>`
    : `<img class="card" loading="lazy" src="${SHOTS_BASE}${t.id}.card.webp" alt="">
       <img class="full" loading="lazy" src="${SHOTS_BASE}${t.id}.full.webp" alt="" style="--ratio:${ratio.toFixed(3)}">`
  const badge = st === 'none' ? '<span class="badge none">实时</span>' : ''
  const chans = t.channels.slice(0, 3).map(c => `<span class="tag ch">${esc(CH_LABEL[c] ?? c)}</span>`).join('')
  return `<article class="frame" data-id="${t.id}" tabindex="0">
    <div class="shot">${shot}<span class="seq">${String(seq).padStart(3,'0')}</span>${badge}</div>
    <div class="meta">
      <div class="t">${esc(t.title ?? '（无标题）')}</div>
      <div class="path">${esc(t.rep.url)}</div>
      <div class="tags">
        <span class="tag">${esc(t.region)}</span>
        ${t.date ? `<span class="tag">${esc(t.date.slice(4))}</span>` : ''}
        ${chans}
        ${t.variantCount > 1 ? `<span class="tag x">×${t.variantCount}</span>` : ''}
        ${t.deployable ? '' : '<span class="tag local">仅本地</span>'}
        ${t.note ? `<span class="tag note">${esc(t.note)}</span>` : ''}
      </div>
    </div>
  </article>`
}

function render(){
  view = sorted(filtered())
  const main = $('#main'), tree = $('#tree')
  document.body.style.setProperty('--card-w', `${state.cardW}px`)

  if (!view.length){
    main.innerHTML = '<div class="empty">没有匹配的页面。<br>换个关键词，或打开 private / 工具页开关。</div>'
    tree.innerHTML = ''
    return
  }

  const flat = state.q.trim() || !state.groupBy
  let seq = 0, html = '', nav = ''

  if (flat){
    html = `<div class="group"><div class="grid">${view.map(t => cardHTML(t, ++seq)).join('')}</div></div>`
  } else {
    const [d1, d2] = state.groupBy.split('+')
    const g1 = new Map()
    for (const t of view){
      const k = keyOf(t, d1)
      if (!g1.has(k)) g1.set(k, [])
      g1.get(k).push(t)
    }
    for (const [k, items] of g1){
      const gid = 'g_' + k.replace(/\W/g, '_')
      nav += `<a data-to="${gid}"><span>${esc(k)}</span><span class="n">${items.length}</span></a>`
      let inner = ''
      if (d2){
        const g2 = new Map()
        for (const t of items){
          const k2 = keyOf(t, d2)
          if (!g2.has(k2)) g2.set(k2, [])
          g2.get(k2).push(t)
        }
        for (const [k2, items2] of g2){
          const sid = gid + '_' + k2.replace(/\W/g, '_')
          if (g2.size > 1){
            nav += `<a class="sub" data-to="${sid}"><span>${esc(k2)}</span><span class="n">${items2.length}</span></a>`
            inner += `<div class="subgroup" id="${sid}"><div class="sub-h">${esc(k2)}<span class="n">${items2.length}</span></div>
              <div class="grid">${items2.map(t => cardHTML(t, ++seq)).join('')}</div></div>`
          } else {
            inner += `<div class="grid">${items2.map(t => cardHTML(t, ++seq)).join('')}</div>`
          }
        }
      } else {
        inner = `<div class="grid">${items.map(t => cardHTML(t, ++seq)).join('')}</div>`
      }
      html += `<section class="group" id="${gid}">
        <div class="group-h"><span class="chev">▼</span><h2>${esc(k)}</h2><span class="n">${items.length}</span></div>
        ${inner}</section>`
    }
  }
  main.innerHTML = html
  tree.innerHTML = nav
  measure()
  mountLive()
}

/* iframe 缩放要的是无单位比例：存纯数字，calc(230px / 390) 会算出长度并让 transform 静默失效 */
function measure(){
  const c = document.querySelector('.frame .shot')
  if (c) document.body.style.setProperty('--card-w-px', String(c.clientWidth))
}
addEventListener('resize', measure)

/* 缺图卡片回源成实时 iframe。
   不用 IntersectionObserver —— 这个项目里它已经出过「内容永远不显示」的事故。
   iframe 原生 loading="lazy" 由浏览器决定何时真正发请求，效果一样且不会失灵。
   MAX_LIVE 是保护阀：一张截图都没有时不至于同时开几百个 iframe。 */
function mountLive(){
  const phs = [...document.querySelectorAll('.placeholder')]
  phs.slice(0, MAX_LIVE).forEach((ph) => {
    const f = document.createElement('iframe')
    f.loading = 'lazy'
    f.setAttribute('sandbox', 'allow-scripts allow-same-origin')
    f.setAttribute('referrerpolicy', 'no-referrer')
    f.src = ph.dataset.live
    const badge = ph.parentElement.querySelector('.badge')
    ph.replaceWith(f)
    badge?.classList.replace('none', 'live')
  })
  phs.slice(MAX_LIVE).forEach((ph) => {
    ph.innerHTML = ONLINE
      ? '未截图<br><span>本地跑 bun run gallery 后重新部署</span>'
      : '未截图 · 超出实时预览上限<br><span>bun run gallery:shots</span>'
  })
}

/* ---------- 抽屉 ---------- */
function openDrawer(id){
  const t = DATA.find(x => x.id === id)
  if (!t) return
  current = t
  const variants = t.variants ?? []
  const opts = variants.map((v, i) => {
    const bits = [v.people ?? v.name, v.version != null ? 'v' + v.version : null, v.t, v.variant]
      .filter(Boolean).join(' · ')
    return `<option value="${i}">${esc(bits || v.url)}</option>`
  }).join('')

  $('#dpanel').innerHTML = `
    <h3>${esc(t.title ?? '（无标题）')}</h3>
    ${t.description ? `<div class="desc">${esc(t.description)}</div>` : ''}
    ${variants.length > 1 ? `<div class="row"><span class="k">变体 · 共 ${t.variantCount}</span>
      <select id="dvariant">${opts}</select></div>` : ''}
    <div class="row"><span class="k">链接</span>
      <div class="linkbar"><span id="lProd"></span><button data-copy="lProd">复制</button>
      <button data-open="lProd">打开</button></div></div>
    <div class="row"><span class="k">明细</span>
      <div class="kv">
        <b>区域</b><span>${esc(t.region)}${t.category ? ' / ' + esc(t.category) : ''}</span>
        <b>日期</b><span>${esc(t.date ?? '—')}${t.serial ? ' · ' + esc(t.serial) : ''}</span>
        <b>渠道</b><span>${t.channels.length ? esc(t.channels.join('、')) : '—'}</span>
        <b>语言</b><span>${esc(t.lang ?? '—')}</span>
        <b>体积</b><span>${Math.round(t.rep.bytes / 1024)} KB</span>
        ${t.deployable ? '' : '<b>部署</b><span style="color:var(--warn)">目录以 _ 结尾，rsync 会跳过，仅本地可见</span>'}
      </div></div>
    <div class="hint"><kbd>←</kbd> <kbd>→</kbd> 切换页面 · <kbd>Esc</kbd> 关闭</div>`

  const setUrl = (i) => {
    const u = (variants[i] ?? { url: t.rep.url }).url
    $('#lProd').textContent = prodUrl(t, u)
    $('#dframe').src = hereUrl(t, u)
  }
  setUrl(0)
  $('#dvariant')?.addEventListener('change', e => setUrl(+e.target.value))

  $('#drawer').classList.add('on')
  $('#scrim').classList.add('on')
}

function closeDrawer(){
  $('#drawer').classList.remove('on')
  $('#scrim').classList.remove('on')
  $('#dframe').src = 'about:blank'
  current = null
}
function step(dir){
  if (!current) return
  const n = view[view.findIndex(t => t.id === current.id) + dir]
  if (n) openDrawer(n.id)
}

/* ---------- 事件 ---------- */
$('#dpanel').addEventListener('click', (e) => {
  const c = e.target.dataset.copy, o = e.target.dataset.open
  if (c){
    navigator.clipboard.writeText($('#' + c).textContent)
    e.target.textContent = '已复制'
    setTimeout(() => { e.target.textContent = '复制' }, 1200)
  }
  if (o) window.open($('#' + o).textContent, '_blank', 'noopener')
})
$('#main').addEventListener('click', (e) => {
  const gh = e.target.closest('.group-h')
  if (gh){ gh.parentElement.classList.toggle('closed'); return }
  const f = e.target.closest('.frame')
  if (f) openDrawer(f.dataset.id)
})
$('#main').addEventListener('keydown', (e) => {
  const f = e.target.closest('.frame')
  if (f && (e.key === 'Enter' || e.key === ' ')){ e.preventDefault(); openDrawer(f.dataset.id) }
})
$('#tree').addEventListener('click', (e) => {
  const a = e.target.closest('a')
  if (!a) return
  document.querySelectorAll('.tree a').forEach(x => x.classList.remove('on'))
  a.classList.add('on')
  document.getElementById(a.dataset.to)?.scrollIntoView({ block: 'start' })
})
$('#scrim').addEventListener('click', closeDrawer)
$('#dclose').addEventListener('click', closeDrawer)

let debounce
$('#q').addEventListener('input', (e) => {
  clearTimeout(debounce)
  debounce = setTimeout(() => { state.q = e.target.value; render() }, 160)
})
$('#groupBy').addEventListener('change', e => { state.groupBy = e.target.value; render() })
$('#sortBy').addEventListener('change', e => { state.sortBy = e.target.value; render() })
$('#segLayout').addEventListener('click', (e) => {
  const b = e.target.closest('button')
  if (!b) return
  $('#segLayout').querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b))
  state.cardW = Number(b.dataset.w)
  render()
})
addEventListener('keydown', (e) => {
  if (e.key === '/' && document.activeElement !== $('#q')){ e.preventDefault(); $('#q').focus() }
  if (e.key === 'Escape'){ if (current) closeDrawer(); else $('#q').blur() }
  if (current && e.key === 'ArrowRight'){ e.preventDefault(); step(1) }
  if (current && e.key === 'ArrowLeft'){ e.preventDefault(); step(-1) }
})

load().catch((err) => {
  $('#main').innerHTML = `<div class="empty">索引读不到：${esc(err.message)}<br><br>
    先跑 <span style="color:var(--ink)">bun run gallery</span> 生成索引与截图。</div>`
})
</script>
</body>
</html>
